args.command:
d=$(mktemp -d); cat > "$d/run.sh" <<'EOF'
#!/bin/bash
export HOME="$d_unused"
run() {
  local label="$1"; local input="$2"
  local out ec
  out=$(printf '%s' "$input" | RICHGO_FORCE_COLOR=1 /workspace/executable testfilter 2>/dev/null | od -An -c); ec=${PIPESTATUS[1]}
  echo "### [$label] variant=noNL exit=$ec"
  printf '%s' "$input" | od -An -c | sed 's/^/IN : /'
  echo "$out" | sed 's/^/OUT: /'
  out=$(printf '%s\n' "$input" | RICHGO_FORCE_COLOR=1 /workspace/executable testfilter 2>/dev/null | od -An -c); ec=${PIPESTATUS[1]}
  echo "### [$label] variant=NL exit=$ec"
  echo "$out" | sed 's/^/OUT: /'
  out=$({ printf '%s\n' "$input"; printf 'zzz\n'; } | RICHGO_FORCE_COLOR=1 /workspace/executable testfilter 2>/dev/null | od -An -c); ec=${PIPESTATUS[1]}
  echo "### [$label] variant=mid(+zzz) exit=$ec"
  echo "$out" | sed 's/^/OUT: /'
}
EOF
chmod +x "$d/run.sh"; echo ok "$d"
